CREATE TABLE public.company_staff_scopes(company_id uuid NOT NULL REFERENCES public.company_profiles(id),user_id uuid NOT NULL,scope text NOT NULL DEFAULT 'approved_employee' CHECK(scope IN ('opportunity_manager','supervisor','approved_employee')),permissions text[] NOT NULL DEFAULT '{}',PRIMARY KEY(company_id,user_id),FOREIGN KEY(company_id,user_id) REFERENCES public.company_memberships(company_id,user_id),CHECK(permissions <@ ARRAY['draft']::text[]));
GRANT SELECT ON public.company_staff_scopes TO authenticated; GRANT ALL ON public.company_staff_scopes TO service_role; ALTER TABLE public.company_staff_scopes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_resource_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.company_profiles(id),user_id uuid NOT NULL,job_id uuid REFERENCES public.jobs(id),placement_id uuid REFERENCES public.placements(id),permissions text[] NOT NULL,FOREIGN KEY(company_id,user_id) REFERENCES public.company_memberships(company_id,user_id),CHECK((job_id IS NULL)<>(placement_id IS NULL)),CHECK(cardinality(permissions)>0 AND permissions <@ ARRAY['read','edit','applications','manage']::text[]));
GRANT SELECT ON public.company_resource_assignments TO authenticated; GRANT ALL ON public.company_resource_assignments TO service_role; ALTER TABLE public.company_resource_assignments ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX company_job_assignment_unique ON public.company_resource_assignments(company_id,user_id,job_id) WHERE job_id IS NOT NULL; CREATE UNIQUE INDEX company_placement_assignment_unique ON public.company_resource_assignments(company_id,user_id,placement_id) WHERE placement_id IS NOT NULL;
CREATE TABLE public.company_permission_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.company_profiles(id),actor_id uuid,subject_id uuid,action text NOT NULL,resource_id uuid,before_state jsonb,after_state jsonb,note text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_permission_events TO authenticated; GRANT SELECT,INSERT ON public.company_permission_events TO service_role; ALTER TABLE public.company_permission_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.company_memberships ADD COLUMN domain_bound boolean NOT NULL DEFAULT false;
UPDATE public.company_memberships m SET domain_bound=true FROM public.employee_identities e WHERE e.user_id=m.user_id AND m.role='employee' AND e.matched_company_id=m.company_id;
ALTER TABLE public.jobs ADD COLUMN publication_revision integer NOT NULL DEFAULT 1;
CREATE TABLE public.job_publication_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.company_profiles(id),job_id uuid NOT NULL REFERENCES public.jobs(id),requested_by uuid NOT NULL,revision integer NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','superseded')),reviewed_by uuid,reviewed_at timestamptz,note text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,revision));
GRANT SELECT ON public.job_publication_requests TO authenticated; GRANT ALL ON public.job_publication_requests TO service_role; ALTER TABLE public.job_publication_requests ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.company_permission(_company_id uuid,_uid uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT EXISTS(SELECT 1 FROM company_memberships m JOIN company_verifications v ON v.company_id=m.company_id JOIN auth.users u ON u.id=m.user_id LEFT JOIN company_staff_scopes s ON s.company_id=m.company_id AND s.user_id=m.user_id WHERE m.company_id=_company_id AND m.user_id=_uid AND u.email_confirmed_at IS NOT NULL AND m.status='approved' AND v.status='verified' AND (m.role='company_admin' OR EXISTS(SELECT 1 FROM employee_identities e WHERE e.user_id=_uid AND e.work_email_verified_at IS NOT NULL AND e.work_email=m.approved_work_email AND (NOT m.domain_bound OR public.employee_domain_company(e.work_email)=m.company_id))) AND CASE _permission WHEN 'admin' THEN m.role='company_admin' WHEN 'member' THEN true WHEN 'draft' THEN m.role='company_admin' OR 'draft'=ANY(s.permissions) WHEN 'placements' THEN m.role='company_admin' OR EXISTS(SELECT 1 FROM company_resource_assignments a WHERE a.company_id=m.company_id AND a.user_id=m.user_id AND a.placement_id IS NOT NULL AND 'manage'=ANY(a.permissions) AND s.scope IN ('supervisor','approved_employee')) ELSE false END)
$$;
CREATE OR REPLACE FUNCTION public.company_can_draft(_company_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT public.company_permission(_company_id,_uid,'draft') OR (NOT EXISTS(SELECT 1 FROM company_memberships WHERE company_id=_company_id AND user_id=_uid AND status IN ('approved','rejected','revoked')) AND EXISTS(SELECT 1 FROM employee_identities e JOIN auth.users u ON u.id=e.user_id WHERE e.user_id=_uid AND u.email_confirmed_at IS NOT NULL AND e.work_email_verified_at IS NOT NULL AND public.employee_domain_company(e.work_email)=_company_id) AND NOT EXISTS(SELECT 1 FROM company_access_requests WHERE company_id=_company_id AND user_id=_uid AND status='rejected'))
$$;
CREATE FUNCTION public.company_job_permission(_job_id uuid,_uid uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT EXISTS(SELECT 1 FROM jobs j WHERE j.id=_job_id AND ((public.company_permission(j.company_id,_uid,'admin') AND (j.status<>'draft' OR j.created_by=_uid OR EXISTS(SELECT 1 FROM job_publication_requests r WHERE r.job_id=j.id AND r.revision=j.publication_revision))) OR (_permission IN ('read','edit') AND j.created_by=_uid AND j.status='draft' AND public.company_can_draft(j.company_id,_uid)) OR (public.company_permission(j.company_id,_uid,'member') AND EXISTS(SELECT 1 FROM company_resource_assignments a JOIN company_staff_scopes s ON s.company_id=a.company_id AND s.user_id=a.user_id WHERE a.company_id=j.company_id AND a.job_id=j.id AND a.user_id=_uid AND s.scope IN ('opportunity_manager','approved_employee') AND (_permission=ANY(a.permissions) OR (_permission='read' AND a.permissions && ARRAY['edit','applications']))))))
$$;
CREATE FUNCTION public.company_application_permission(_application_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM applications a JOIN jobs j ON j.id::text=a.job_id WHERE a.id=_application_id AND public.company_job_permission(j.id,_uid,'applications')) $$;
CREATE OR REPLACE FUNCTION public.can_manage_placement(_placement_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM placements p WHERE p.id=_placement_id AND (public.company_permission(p.company_id,_uid,'admin') OR (public.company_permission(p.company_id,_uid,'member') AND EXISTS(SELECT 1 FROM company_resource_assignments a JOIN company_staff_scopes s ON s.company_id=a.company_id AND s.user_id=a.user_id WHERE a.company_id=p.company_id AND a.placement_id=p.id AND a.user_id=_uid AND s.scope IN ('supervisor','approved_employee') AND 'manage'=ANY(a.permissions))))) $$;
CREATE OR REPLACE FUNCTION public.is_placement_employer(_application_id uuid,_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM placements p WHERE p.application_id=_application_id AND public.can_manage_placement(p.id,_user_id)) $$;
CREATE FUNCTION public.company_application_read(_application_id uuid,_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.company_application_permission(_application_id,_uid) OR public.is_placement_employer(_application_id,_uid) $$;
REVOKE ALL ON FUNCTION public.company_job_permission(uuid,uuid,text),public.company_application_permission(uuid,uuid),public.company_application_read(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.company_job_permission(uuid,uuid,text),public.company_application_permission(uuid,uuid),public.company_application_read(uuid,uuid) TO authenticated,service_role;
CREATE POLICY "Own or administrator staff scopes" ON public.company_staff_scopes FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.company_permission(company_id,auth.uid(),'member')) OR public.company_permission(company_id,auth.uid(),'admin'));
CREATE POLICY "Own or administrator assignments" ON public.company_resource_assignments FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.company_permission(company_id,auth.uid(),'member')) OR public.company_permission(company_id,auth.uid(),'admin'));
CREATE POLICY "Administrators read permission history" ON public.company_permission_events FOR SELECT TO authenticated USING(public.company_permission(company_id,auth.uid(),'admin') OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Own publication requests or company approval" ON public.job_publication_requests FOR SELECT TO authenticated USING((requested_by=auth.uid() AND public.company_job_permission(job_id,auth.uid(),'read')) OR public.company_permission(company_id,auth.uid(),'admin'));
CREATE POLICY "Company administrators read staff" ON public.company_memberships FOR SELECT TO authenticated USING(public.company_permission(company_id,auth.uid(),'admin'));
DROP POLICY "Company authorised job reads" ON public.jobs; CREATE POLICY "Company authorised job reads" ON public.jobs FOR SELECT TO authenticated USING(public.company_job_permission(id,auth.uid(),'read'));
DROP POLICY "Company authorised job updates" ON public.jobs; CREATE POLICY "Company authorised job updates" ON public.jobs FOR UPDATE TO authenticated USING(public.company_job_permission(id,auth.uid(),'edit')) WITH CHECK(public.company_job_permission(id,auth.uid(),'edit'));
DROP POLICY "Company authorised application reads" ON public.applications; CREATE POLICY "Company authorised application reads" ON public.applications FOR SELECT TO authenticated USING(public.company_application_read(id,auth.uid()));
DROP POLICY "Company authorised application updates" ON public.applications; CREATE POLICY "Company authorised application updates" ON public.applications FOR UPDATE TO authenticated USING(public.company_application_permission(id,auth.uid())) WITH CHECK(public.company_application_permission(id,auth.uid()));
CREATE FUNCTION public.audit_company_permission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; a jsonb; c uuid; s uuid; r uuid; BEGIN IF TG_OP<>'INSERT' THEN b:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN a:=to_jsonb(NEW); END IF; c:=coalesce((a->>'company_id')::uuid,(b->>'company_id')::uuid); s:=coalesce((a->>'user_id')::uuid,(b->>'user_id')::uuid); r:=coalesce((a->>'id')::uuid,(b->>'id')::uuid,c); INSERT INTO company_permission_events(company_id,actor_id,subject_id,action,resource_id,before_state,after_state,note) VALUES(c,auth.uid(),s,TG_TABLE_NAME||':'||lower(TG_OP),r,CASE WHEN b IS NULL THEN NULL ELSE jsonb_build_object('role',b->'role','status',b->'status','scope',b->'scope','permissions',b->'permissions','job_id',b->'job_id','placement_id',b->'placement_id','approved',b->'approved','domain',b->'domain','revision',b->'revision') END,CASE WHEN a IS NULL THEN NULL ELSE jsonb_build_object('role',a->'role','status',a->'status','scope',a->'scope','permissions',a->'permissions','job_id',a->'job_id','placement_id',a->'placement_id','approved',a->'approved','domain',a->'domain','revision',a->'revision') END,nullif(current_setting('app.permission_note',true),'')); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER audit_company_membership AFTER INSERT OR UPDATE OR DELETE ON public.company_memberships FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission(); CREATE TRIGGER audit_company_scope AFTER INSERT OR UPDATE OR DELETE ON public.company_staff_scopes FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission(); CREATE TRIGGER audit_company_assignment AFTER INSERT OR UPDATE OR DELETE ON public.company_resource_assignments FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission(); CREATE TRIGGER audit_company_domain AFTER INSERT OR UPDATE OR DELETE ON public.company_domains FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission(); CREATE TRIGGER audit_company_verification AFTER INSERT OR UPDATE ON public.company_verifications FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission(); CREATE TRIGGER audit_company_publication AFTER INSERT OR UPDATE ON public.job_publication_requests FOR EACH ROW EXECUTE FUNCTION public.audit_company_permission();
CREATE FUNCTION public.guard_permission_history() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Permission history is append-only'; END $$; CREATE TRIGGER immutable_permission_history BEFORE UPDATE OR DELETE ON public.company_permission_events FOR EACH ROW EXECUTE FUNCTION public.guard_permission_history();
CREATE FUNCTION public.guard_company_membership_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.approved_work_email IS DISTINCT FROM OLD.approved_work_email THEN NEW.domain_bound:=NEW.role<>'company_admin' AND EXISTS(SELECT 1 FROM employee_identities e WHERE e.user_id=NEW.user_id AND public.employee_domain_company(e.work_email)=NEW.company_id); END IF; RETURN NEW; END $$; CREATE TRIGGER bind_membership_domain BEFORE INSERT OR UPDATE ON public.company_memberships FOR EACH ROW EXECUTE FUNCTION public.guard_company_membership_scope();
CREATE FUNCTION public.set_company_staff_access(_company_id uuid,_user_id uuid,_scope text,_draft boolean,_revoke boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m company_memberships%ROWTYPE; BEGIN PERFORM 1 FROM company_verifications WHERE company_id=_company_id FOR UPDATE; IF NOT public.company_permission(_company_id,auth.uid(),'admin') OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Company administrator required'; END IF; IF _user_id=auth.uid() OR _scope IS NULL OR _scope NOT IN ('opportunity_manager','supervisor','approved_employee') OR _draft IS NULL OR _revoke IS NULL OR length(btrim(coalesce(_note,''))) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Choose staff scope and document the reason'; END IF; SELECT * INTO m FROM company_memberships WHERE company_id=_company_id AND user_id=_user_id FOR UPDATE; IF NOT FOUND OR m.role='company_admin' OR m.status<>'approved' THEN RAISE EXCEPTION 'Only approved non-administrator staff can be managed here'; END IF; PERFORM set_config('app.permission_note',btrim(_note),true); IF _revoke THEN UPDATE company_memberships SET status='revoked',manage_placements=false WHERE id=m.id; DELETE FROM company_resource_assignments WHERE company_id=_company_id AND user_id=_user_id; DELETE FROM company_staff_scopes WHERE company_id=_company_id AND user_id=_user_id; ELSE IF NOT public.company_permission(_company_id,_user_id,'member') THEN RAISE EXCEPTION 'Current work email and company verification required'; END IF; IF EXISTS(SELECT 1 FROM company_staff_scopes WHERE company_id=_company_id AND user_id=_user_id AND scope<>_scope) THEN DELETE FROM company_resource_assignments WHERE company_id=_company_id AND user_id=_user_id; END IF; INSERT INTO company_staff_scopes(company_id,user_id,scope,permissions) VALUES(_company_id,_user_id,_scope,CASE WHEN _draft THEN ARRAY['draft'] ELSE '{}' END) ON CONFLICT(company_id,user_id) DO UPDATE SET scope=excluded.scope,permissions=excluded.permissions; END IF; PERFORM public._notify(_user_id,'company','staff-access:'||gen_random_uuid()::text,'Company permissions updated','Your company access status has changed.','Your authorised company permissions have changed.','/employer/workspace'); END $$;
CREATE FUNCTION public.set_company_resource_assignment(_company_id uuid,_user_id uuid,_job_id uuid,_placement_id uuid,_permissions text[],_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sc text; BEGIN PERFORM 1 FROM company_verifications WHERE company_id=_company_id FOR UPDATE; IF auth.uid() IS NULL OR NOT public.company_permission(_company_id,auth.uid(),'admin') THEN RAISE EXCEPTION 'Company administrator required'; END IF; SELECT scope INTO sc FROM company_staff_scopes WHERE company_id=_company_id AND user_id=_user_id; IF NOT public.company_permission(_company_id,_user_id,'member') OR sc IS NULL THEN RAISE EXCEPTION 'Approved scoped staff required'; END IF; IF (_job_id IS NULL)=(_placement_id IS NULL) OR length(btrim(coalesce(_note,''))) NOT BETWEEN 10 AND 2000 OR _permissions IS NULL THEN RAISE EXCEPTION 'Choose one resource and document the assignment'; END IF; IF _job_id IS NOT NULL THEN IF sc NOT IN ('opportunity_manager','approved_employee') OR NOT EXISTS(SELECT 1 FROM jobs WHERE id=_job_id AND company_id=_company_id) OR NOT (_permissions <@ ARRAY['read','edit','applications']::text[]) THEN RAISE EXCEPTION 'Invalid opportunity assignment'; END IF; ELSE IF sc NOT IN ('supervisor','approved_employee') OR NOT EXISTS(SELECT 1 FROM placements WHERE id=_placement_id AND company_id=_company_id) OR NOT (_permissions <@ ARRAY['manage']::text[]) THEN RAISE EXCEPTION 'Invalid placement assignment'; END IF; END IF; PERFORM set_config('app.permission_note',btrim(_note),true); DELETE FROM company_resource_assignments WHERE company_id=_company_id AND user_id=_user_id AND (job_id=_job_id OR placement_id=_placement_id); IF cardinality(_permissions)>0 THEN INSERT INTO company_resource_assignments(company_id,user_id,job_id,placement_id,permissions) VALUES(_company_id,_user_id,_job_id,_placement_id,_permissions); END IF; END $$;
CREATE OR REPLACE FUNCTION public.guard_company_job() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Job ownership cannot be changed'; END IF; NEW.publication_revision:=OLD.publication_revision+1; UPDATE job_publication_requests SET status='superseded' WHERE job_id=OLD.id AND status='pending' AND id::text IS DISTINCT FROM current_setting('app.publication_request',true); ELSE NEW.publication_revision:=1; IF auth.uid() IS NOT NULL THEN NEW.created_by:=auth.uid(); END IF; END IF; IF auth.uid() IS NOT NULL AND NEW.status='active' AND NOT public.company_permission(NEW.company_id,auth.uid(),'admin') THEN IF TG_OP='UPDATE' AND OLD.status='active' AND public.company_job_permission(OLD.id,auth.uid(),'edit') THEN NEW.status:='draft'; ELSE RAISE EXCEPTION 'Company administrator approval is required for public publication'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.audit_public_job() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='active' THEN INSERT INTO job_publication_requests(company_id,job_id,requested_by,revision,status,reviewed_by,reviewed_at,note) VALUES(NEW.company_id,NEW.id,coalesce(auth.uid(),NEW.created_by),NEW.publication_revision,'approved',auth.uid(),now(),'Publication approved for this revision') ON CONFLICT(job_id,revision) DO NOTHING; END IF; RETURN NEW; END $$; CREATE TRIGGER audit_public_job AFTER INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.audit_public_job();
CREATE FUNCTION public.request_job_publication(_job_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jobs%ROWTYPE; rid uuid; BEGIN SELECT * INTO j FROM jobs WHERE id=_job_id FOR UPDATE; IF auth.uid() IS NULL OR NOT FOUND OR j.status<>'draft' OR NOT public.company_job_permission(j.id,auth.uid(),'edit') THEN RAISE EXCEPTION 'An authorised draft is required'; END IF; INSERT INTO job_publication_requests(company_id,job_id,requested_by,revision) VALUES(j.company_id,j.id,auth.uid(),j.publication_revision) ON CONFLICT(job_id,revision) DO UPDATE SET status='pending',requested_by=excluded.requested_by,reviewed_by=NULL,reviewed_at=NULL,note=NULL RETURNING id INTO rid; RETURN rid; END $$;
CREATE FUNCTION public.review_job_publication(_request_id uuid,_approve boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r job_publication_requests%ROWTYPE; j jobs%ROWTYPE; BEGIN SELECT j0.* INTO j FROM jobs j0 JOIN job_publication_requests r0 ON r0.job_id=j0.id WHERE r0.id=_request_id FOR UPDATE OF j0; SELECT * INTO r FROM job_publication_requests WHERE id=_request_id FOR UPDATE; IF auth.uid() IS NULL OR r.id IS NULL OR NOT public.company_permission(r.company_id,auth.uid(),'admin') THEN RAISE EXCEPTION 'Company administrator approval required'; END IF; IF _approve IS NULL OR r.status<>'pending' OR j.status<>'draft' OR r.revision<>j.publication_revision OR length(btrim(coalesce(_note,''))) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Review the current draft revision and record your decision'; END IF; IF NOT public.company_job_permission(j.id,r.requested_by,'edit') THEN RAISE EXCEPTION 'Contributor access changed; request a fresh authorised review'; END IF; PERFORM set_config('app.permission_note',btrim(_note),true); UPDATE job_publication_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,reviewed_by=auth.uid(),reviewed_at=now(),note=btrim(_note) WHERE id=r.id; IF _approve THEN PERFORM set_config('app.publication_request',r.id::text,true); UPDATE jobs SET status='active' WHERE id=j.id; END IF; PERFORM public._notify(r.requested_by,'company','publication-review:'||r.id::text||':'||gen_random_uuid()::text,'Opportunity approval update','Your company approval status has changed.',CASE WHEN _approve THEN 'Your opportunity has been approved for publication.' ELSE 'Your opportunity was not approved for publication.' END,'/employer/drafts?company='||r.company_id::text); END $$;
REVOKE ALL ON FUNCTION public.set_company_staff_access(uuid,uuid,text,boolean,boolean,text),public.set_company_resource_assignment(uuid,uuid,uuid,uuid,text[],text),public.request_job_publication(uuid),public.review_job_publication(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_company_staff_access(uuid,uuid,text,boolean,boolean,text),public.set_company_resource_assignment(uuid,uuid,uuid,uuid,text[],text),public.request_job_publication(uuid),public.review_job_publication(uuid,boolean,text) TO authenticated;
COMMENT ON COLUMN public.company_memberships.manage_placements IS 'DEPRECATED: operational access comes only from company_resource_assignments and company_staff_scopes';
DO $migration$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.submit_reference(uuid,text,text,text,text,text,text)'::regprocedure) INTO d; d:=replace(d,'NOT EXISTS (SELECT 1 FROM placements p JOIN company_profiles c ON c.id=p.company_id WHERE p.id=_placement_id AND c.user_id=auth.uid())','NOT public.can_manage_placement(_placement_id,auth.uid())'); EXECUTE d; SELECT pg_get_functiondef('public.update_reference(uuid,text,text,text,text,text,text)'::regprocedure) INTO d; d:=replace(d,'r.author_id <> auth.uid()','r.author_id <> auth.uid() OR auth.uid() IS NULL OR NOT public.can_manage_placement(r.placement_id,auth.uid())'); EXECUTE d; SELECT pg_get_functiondef('public.withdraw_reference(uuid)'::regprocedure) INTO d; d:=replace(d,'r.author_id <> auth.uid()','r.author_id <> auth.uid() OR auth.uid() IS NULL OR NOT public.can_manage_placement(r.placement_id,auth.uid())'); EXECUTE d; SELECT pg_get_functiondef('public.get_company_access()'::regprocedure) INTO d; d:=replace(d,'''manage_placements'',public.company_permission(c.id,uid,''placements'')','''scope'',CASE WHEN public.company_permission(c.id,uid,''admin'') THEN ''company_admin'' WHEN public.company_permission(c.id,uid,''member'') THEN coalesce((SELECT s.scope FROM company_staff_scopes s WHERE s.company_id=c.id AND s.user_id=uid),''approved_employee'') WHEN public.company_can_draft(c.id,uid) THEN ''draft_contributor'' ELSE NULL END,''can_draft'',public.company_can_draft(c.id,uid),''manage_placements'',public.company_permission(c.id,uid,''placements'')'); EXECUTE d; END $migration$;